 const [serverSlots,setServerSlots]=useState<string[]>([]);const [slotsLoading,setSlotsLoading]=useState(false);const [slotsFor,setSlotsFor]=useState('');const [slotsRefresh,setSlotsRefresh]=useState(0);const requestedSlotsKey=`${bookingDate}|${bookingMaster}|${bookingServices.join(',')}`;
 const occupied=state.bookings.filter(b=>b.date===bookingDate&&b.status!=='cancelled');
 const freeTimes=times.filter(t=>{const st=Number(t.slice(0,2))*60+Number(t.slice(3));if(st+Math.max(duration,30)>19*60)return false;if(state.blocked.includes(`${bookingDate}|${t}`)||state.blocked.includes(`${bookingMaster}|${bookingDate}|${t}`))return false;if(bookingDate===today()){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bishkek',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const n=Number(parts.find(p=>p.type==='hour')?.value||0)*60+Number(parts.find(p=>p.type==='minute')?.value||0);if(st<=n+30)return false}return !occupied.some(b=>{if(bookingMaster!=='any'&&b.masterId!==bookingMaster&&b.masterId!=='any')return false;const bst=Number(b.time.slice(0,2))*60+Number(b.time.slice(3));const bd=b.serviceIds.reduce((n,id)=>n+(state.services.find(s=>s.id===id)?.duration||30),0);return st<bst+bd&&st+duration>bst})});
