 const wa=(msg:string)=>{const number=(state.content.whatsapp||import.meta.env.VITE_SALON_WHATSAPP||'').replace(/\D/g,'');if(!number){alert(t('Номер WhatsApp пока не указан. Пожалуйста, свяжитесь с салоном другим способом.'));return}{const popup=window.open(`https://wa.me/${number}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer');if(popup)alert(t('WhatsApp открыт — нажмите «Отправить» в чате.'));else alert(t('Разрешите всплывающие окна, чтобы открыть WhatsApp.'))}};
 const sendBookingToWhatsapp=()=>{
   if(!picked.length){alert(t('Сначала выберите услуги.'));return;}
   if(customer.name.trim().length<2||!validatePhone(bookingPhoneCountry,customer.phone)||!consent){
     alert(t('Укажите имя, телефон и подтвердите согласие, чтобы связаться с салоном.'));return;
   }
   const masterName=state.masters.find(m=>m.id===bookingMaster)?.name||'Любой подходящий мастер';
   const lines=[
     'Здравствуйте! Хочу согласовать запись в EL BEM.',
     `Имя: ${safeText(customer.name.trim())}`,
     `Телефон: ${composePhone(bookingPhoneCountry,customer.phone)}`,
     'Услуги:',
     ...picked.map(s=>`• ${s.name} — ${s.duration} мин, ${money(s.price)}`),
     `Всего: ${duration} мин, ориентировочно ${money(total)}`,
     `Желаемая дата: ${bookingDate}`,
     `Мастер: ${masterName}`,
     bookingTime&&!needsWhatsappBooking?`Удобное время: ${bookingTime}`:'Время: согласовать с салоном',
     customer.note.trim()?`Пожелания: ${safeText(customer.note.trim())}`:''
   ];
   // WhatsApp is a request for consultation, not a saved Firebase booking.
   wa(lines.filter(Boolean).join('\n'));
 };
 const submitBooking=async()=>{if(bookingBusy)return;if(!configured){notify(t('Онлайн-запись временно недоступна. Свяжитесь с салоном.'),'error');return;}if(needsWhatsappBooking){sendBookingToWhatsapp();return;}if(configured&&!auth?.currentUser){setAuthMode('signup');setAuthOpen(true);alert(t('Для записи создайте аккаунт или войдите.'));return;}if(!picked.length||!bookingTime||!displayedTimes.includes(bookingTime)||!customer.name.trim()||!validatePhone(bookingPhoneCountry,customer.phone)||!consent){alert(t('Проверьте выбранные услуги, время, имя, телефон и согласие'));return}setBookingBusy(true);notify(t('Отправляем заявку…'),'pending');const b:Booking={id:uid(),name:safeText(customer.name),phone:composePhone(bookingPhoneCountry,customer.phone),date:bookingDate,time:bookingTime,masterId:bookingMaster,serviceIds:bookingServices,total,status:'pending',note:safeText(customer.note),createdAt:new Date().toISOString()};try{if(configured){const saved=await createBooking(b);b.id=saved.id;b.masterId=saved.masterId;b.total=saved.total}change('bookings',[b,...state.bookings]);setMyBookings(old=>old.some(x=>x.id===b.id)?old:[b,...old]);setSubmitted(b);setBookingTime('');notify(t('Ваша заявка отправлена'),'success')}catch(e){{console.error('Booking error',e);setBookingTime('');setSlotsRefresh(n=>n+1);notify(t('Не удалось отправить заявку. Попробуйте другое время.')+' '+saveErrorText(e),'error')}}finally{setBookingBusy(false)}};
 const cartTotal=Object.entries(cart).reduce((sum,[id,n])=>sum+(state.products.find(p=>p.id===id)?.price||0)*n,0);
 const [orderSuccess,setOrderSuccess]=useState<Order|null>(null);const [orderChannel,setOrderChannel]=useState<'whatsapp'|'telegram'>('whatsapp');const [orderName,setOrderName]=useState('');const[orderPhone,setOrderPhone]=useState('');const[orderPhoneCountry,setOrderPhoneCountry]=useState<PhoneCountry>('KG');const [orderBusy,setOrderBusy]=useState(false);const [bookingBusy,setBookingBusy]=useState(false);
 const submitOrder=async(channel:'whatsapp'|'telegram'='whatsapp')=>{if(orderBusy)return;if(!configured){notify(t('Оформление заказа временно недоступно.'),'error');return;}if(configured&&!auth?.currentUser){setAuthMode('signup');setAuthOpen(true);alert(t('Для оформления заказа войдите или зарегистрируйтесь.'));return;}if(Object.keys(cart).length>8){alert(t('В одном заказе можно оформить до 8 разных товаров. Разделите корзину на два заказа.'));return;}if(!orderName.trim()||!validatePhone(orderPhoneCountry,orderPhone)||!Object.keys(cart).some(id=>cart[id]>0)){alert(t('Проверьте имя, номер телефона и корзину'));return}
  setOrderBusy(true);notify(t('Отправляем заказ…'),'pending');
  const telegramLink=telegramOwnerLink();
  if(channel==='telegram'&&!telegramLink){setOrderBusy(false);notify(t('Telegram владельца не настроен.'),'error');return}
  // External chat is opened by the client from the confirmed order screen, never as a blank pending popup.
  const order:Order={id:uid(),name:orderName.trim(),phone:composePhone(orderPhoneCountry,orderPhone),items:Object.entries(cart).filter(([,qty])=>qty>0).map(([id,quantity])=>({id,quantity,price:state.products.find(p=>p.id===id)?.price||0,name:state.products.find(p=>p.id===id)?.name||id})),total:cartTotal,date:new Date().toISOString(),status:'pending'};
  try{
    const saved=await makeOrder(order);
    change('orders',[saved,...state.orders]);setMyOrders(old=>old.some(x=>x.id===saved.id)?old:[saved,...old]);
    setCart({});setOrderChannel(channel);setOrderSuccess(saved);
    notify(t('Заказ успешно отправлен'),'success');
  }catch(e){console.error('Order error',e);notify(t('Не удалось оформить заказ. Попробуйте ещё раз.')+' '+saveErrorText(e),'error')}
  finally{setOrderBusy(false)}
 };
 const googleLogin=async()=>{
   if(authBusy)return;
   setAuthError('');
   if(!configured||!auth){setAuthError(t('Сервис временно недоступен. Попробуйте позже.'));return;}
   setAuthBusy(true);notify(t('Проверяем данные аккаунта…'),'pending');
   try{
     const provider=new GoogleAuthProvider();
     provider.setCustomParameters({prompt:'select_account'});
     await signInWithPopup(auth,provider);
     setAuthPass('');setAuthOpen(false);
     notify(t('Вход выполнен'),'success');
   }catch(error){
     const code=typeof error==='object'&&error!==null&&'code' in error?String(error.code):'';
     if(code==='auth/popup-closed-by-user'||code==='auth/cancelled-popup-request'){
       notify(t('Вход отменён'),'info');return;
     }
     const message=code==='auth/unauthorized-domain'
       ?t('Домен сайта не разрешён в Firebase Authentication. Добавьте домен в Authorized domains.')
       :code==='auth/invalid-api-key'||code==='auth/app-not-authorized'
       ?t('Проверьте Firebase API key и ограничения ключа в Google Cloud.')
       :code==='auth/operation-not-allowed'
       ?t('Включите Google в Firebase Authentication')
       :code==='auth/popup-blocked'
       ?t('Разрешите всплывающие окна для Google')
       :formatAuthError(error,t);
     const diagnostic=code?`${message} [${code}]`:message;
     console.error('Google sign-in failed:',error);
     setAuthError(diagnostic);notify(diagnostic,'error');
   }finally{setAuthBusy(false)}
 };
 const login=async()=>{if(authBusy)return;setAuthError('');if(!/^\S+@\S+\.\S+$/.test(authEmail.trim())){setAuthError(t('Введите корректный email.'));return}if(authPass.length<6){setAuthError(t('Пароль должен содержать не менее 6 символов'));return}if(!configured||!auth){setAuthError('Регистрация будет доступна после подключения системы личных кабинетов.');return}setAuthBusy(true);notify(t('Проверяем данные аккаунта…'),'pending');try{if(authMode==='signup'){
   if(!validatePhone(authPhoneCountry,authPhone))throw Error(t('Проверьте номер для выбранной страны'));
   await createUserWithEmailAndPassword(auth,authEmail.trim(),authPass);
   const internationalPhone=composePhone(authPhoneCountry,authPhone);
   try{await saveClientPhone(internationalPhone)}catch(profileError){
     console.error('Client phone profile save failed after successful registration',profileError);
     alert(t('Аккаунт создан, но телефон не удалось сохранить. Повторите сохранение позже.'));
   }
   setCustomer(old=>({...old,phone:authPhone}));setBookingPhoneCountry(authPhoneCountry);
   setOrderPhone(authPhone);setOrderPhoneCountry(authPhoneCountry);
 }else await signInWithEmailAndPassword(auth,authEmail.trim(),authPass);
 setAuthPass('');setAuthOpen(false);notify(t(authMode==='signup'?'Аккаунт создан':'Вход выполнен'),'success')}catch(e){const message=formatAuthError(e,t);setAuthError(message);notify(message,'error')}finally{setAuthBusy(false)}};
  // Owner login is independent from customer login; Firebase validates one owner account.
  // Admin authentication uses a separate Firebase account and a verified server-side admin custom claim.
  const adminLogin=async()=>{
    if(adminBusy)return;
    setAuthError('');
    const ownerEmail=adminEmail.trim();
    if(!configured||!ownerFirebaseAuth){setAuthError(t('Сервис временно недоступен. Попробуйте позже.'));return;}
    if(!import.meta.env.VITE_ADMIN_LOGIN_EMAIL){setAuthError('Не настроен email администратора (VITE_ADMIN_LOGIN_EMAIL).');return;}
    if(ownerEmail.toLowerCase()!==import.meta.env.VITE_ADMIN_LOGIN_EMAIL.trim().toLowerCase()){setAuthError(t('Для этого email вход в админку не разрешён.'));return;}
    if(!/^\S+@\S+\.\S+$/.test(ownerEmail)){setAuthError(t('Введите корректный email.'));return;}
    if(!adminPass){setAuthError(t('Введите пароль.'));return;}
    setAdminBusy(true);
    try{
     
await setPersistence(ownerFirebaseAuth,browserSessionPersistence);
await signInWithEmailAndPassword(ownerFirebaseAuth,ownerEmail,adminPass);

      if(!await checkAdmin(true)){
        await signOut(ownerFirebaseAuth);
        throw new Error('Для этой учётной записи не назначена роль администратора.');
      }
      setAdminAuth(true);
      setAdminPass('');
    }catch(error){
      setAdminAuth(false);
      const code=(error as {code?:string}).code;
      setAuthError(['auth/invalid-credential','auth/wrong-password','auth/user-not-found'].includes(code||'')?t('Неверный email или пароль администратора.'):formatAuthError(error,t));
    }finally{setAdminBusy(false)}
  };

  const openAdmin=()=>{audio.current?.pause();setAudioOn(false);setMenu(false);setAdmin(true);setPage('Админка');setMenu(false);navigate('/admin');if(!configured)setAdminAuth(false);window.scrollTo(0,0)};
 const content=state.content;
 const offers=content.promotions??defaultOffers;
 const visibleOffers=offers.filter(offer=>offer.active&&offer.name.trim());
 // The newest active offer is shown first, so newly saved promotions are immediately visible.
 const firstOffer=visibleOffers.at(-1);
 const [dismissedPromotion,setDismissedPromotion]=useState<string|null>(null);
 const [promoEdit,setPromoEdit]=useState<Promotion|null>(null);const [promotionBusy,setPromotionBusy]=useState(false);
 const musicAvailable=Boolean(content.musicEnabled&&content.musicUrl&&!admin);
 const musicVolume=Math.max(0,Math.min(100,Number(content.musicVolume??30)));const [volumeDirty,setVolumeDirty]=useState(false);const [volumeState,setVolumeState]=useState<'idle'|'saving'|'saved'|'error'>('idle');
 volumeRef.current=musicVolume;
 useEffect(()=>{if(!adminAuth||!volumeDirty||!configured)return;const volume=musicVolume;const timer=window.setTimeout(()=>{
  setVolumeState('saving');
  volumeWriteQueue.current=volumeWriteQueue.current.catch(()=>undefined).then(()=>saveEntity('site_content',{id:'main',data:{musicVolume:volume}}));
  void volumeWriteQueue.current.then(()=>{if(volumeRef.current===volume){volumeEditInProgress.current=false;setVolumeState('saved');setVolumeDirty(false)}})
   .catch(error=>{console.error('Music volume save',error);if(volumeRef.current===volume)setVolumeState('error')});
 },240);return()=>window.clearTimeout(timer)},[musicVolume,volumeDirty,adminAuth]);
 const togglePublicMusic=async(enabled:boolean)=>{
  if(!configured||!adminAuth){notify(t('Войдите в административный аккаунт перед сохранением.'),'error');return}
  setState(old=>({...old,content:{...old.content,musicEnabled:enabled}}));
  setMusicVisibilityBusy(true);notify(t('Сохраняем настройки музыки…'),'pending');
  try{
    volumeWriteQueue.current=volumeWriteQueue.current.catch(()=>undefined).then(()=>saveEntity('site_content',{id:'main',data:{musicEnabled:enabled}}));
    await volumeWriteQueue.current;
    notify(enabled?t('Значок музыки включён на сайте'):t('Значок музыки скрыт на сайте'),'success');
  }catch(error){console.error('Music visibility save',error);notify(saveErrorText(error),'error');setState(old=>({...old,content:{...old.content,musicEnabled:!enabled}}))}
  finally{setMusicVisibilityBusy(false)}
 };
 useEffect(()=>{if(audio.current)audio.current.volume=musicVolume/100},[musicVolume,content.musicUrl,admin]);
 useEffect(()=>{
   const player=audio.current;
   if(!player||!musicAvailable||musicUserPaused){player?.pause();setAudioOn(false);return}
   let active=true;
   const attempt=()=>{
     if(!active||!audio.current||document.visibilityState==='hidden'||!audio.current.paused)return;
     void audio.current.play().then(()=>{if(active)setAudioOn(true)}).catch(()=>{if(active)setAudioOn(false)});
   };
   attempt();
   // Audible autoplay is restricted by Chrome/Safari/Firefox until an interaction.
   window.addEventListener('pointerdown',attempt,true);
   window.addEventListener('keydown',attempt,true);
   return()=>{active=false;window.removeEventListener('pointerdown',attempt,true);window.removeEventListener('keydown',attempt,true);player.pause()};
 },[musicAvailable,content.musicUrl,musicUserPaused,admin]);
 const addProduct=(product:Product)=>{
  setOrderSuccess(null);
   if((cart[product.id]||0)>=20){alert(t('В корзине можно выбрать не более 20 единиц одного товара.'));return}
   setCart(old=>({...old,[product.id]:Math.min(20,(old[product.id]||0)+1)}));
   setAddedProductId(product.id);
   if(addedProductTimer.current)clearTimeout(addedProductTimer.current);
   addedProductTimer.current=setTimeout(()=>setAddedProductId(null),1800);
 };

