 const MastersPage=()=> <Section eyebrow="КОМАНДА" title="Наши мастера"><div className="master-grid">{activeMasters.map(m=><article className="master-card large" key={m.id}><button type="button" className="master-photo-button" onClick={()=>openDetail('master',m.id)} aria-label={`Подробнее о мастере: ${itemText(m,'name',m.name)}`}><MediaImage src={m.image} alt={itemText(m,'name',m.name)}/></button><button type="button" className="detail-title" onClick={()=>openDetail('master',m.id)}><h3>{itemText(m,'name',m.name)}</h3></button><p>{itemText(m,'specialty',m.specialty)}</p><button className="btn btn-outline" onClick={()=>{setBookingMaster(m.id);go('Запись')}}>{t("Выбрать мастера")} <ArrowUpRight size={16}/></button></article>)}</div></Section>;
 const BookingPage=()=> <Section eyebrow="ОНЛАЙН-ЗАПИСЬ" title="Время для себя">{submitted?<div className="success-box"><Check size={35}/><h3>{t("Ваша заявка отправлена")}</h3><p>{t("Номер:")} {submitted.id.slice(0,8)}{t(". Ожидайте подтверждения администратора.")}</p><button className="btn btn-primary" onClick={()=>wa(`Здравствуйте! Заявка EL BEM №${submitted.id.slice(0,8)}. ${submitted.name}, ${submitted.phone}. Услуги: ${submitted.serviceIds.map(id=>state.services.find(s=>s.id===id)?.name).join(', ')}. Дата: ${submitted.date}, время: ${submitted.time}.`)}>{t("Отправить в WhatsApp")} <ArrowUpRight size={17}/></button><button className="btn btn-outline" onClick={()=>go('Кабинет')}>{t('Перейти в мои записи')} <ArrowRight size={16}/></button><button className="text-link" onClick={()=>{setSubmitted(null);setBookingServices([]);setBookingTime('')}}>{t("Новая запись")}</button></div>:<div className="booking-layout"><div className="booking-main"><div className="booking-step"><h3><span>01</span>  {t("Выберите услуги")}</h3><p>{t("Можно выбрать одну или несколько процедур.")}</p><div className="service-choices">{activeServices.map(s=><button className={bookingServices.includes(s.id)?'checked':''} key={s.id} onClick={()=>{setBookingServices(old=>old.includes(s.id)?old.filter(id=>id!==s.id):[...old,s.id]);setBookingTime('')}}><span className="choice-check">{bookingServices.includes(s.id)?<Check size={14}/>:<Plus size={14}/>}</span><span>{itemText(s,'name',s.name)}<small>{s.duration}  {t("мин")}</small></span><strong><MoneyAmount amount={s.price} from/></strong></button>)}</div></div><div className="booking-step"><h3><span>02</span>  {t("Выберите мастера")}</h3><p>{t("Выбор необязателен — мы можем подобрать специалиста.")}</p><div className="master-options"><button className={bookingMaster==='any'?'selected':''} onClick={()=>setBookingMaster('any')}>{t("Любой подходящий мастер")}</button>{possibleMasters.map(m=><button key={m.id} className={bookingMaster===m.id?'selected':''} onClick={()=>setBookingMaster(m.id)}>{itemText(m,'name',m.name)}</button>)}<button className={bookingMaster==='onsite'?'selected':''} onClick={()=>setBookingMaster('onsite')}>{t("Уточнить мастера на месте")}</button></div></div><div className="booking-step"><h3><span>03</span>  {t("Выберите день и время")}</h3><label className="field">{t("Дата")} * <input type="date" min={today()} max={nextBookingLimit()} required value={bookingDate} onChange={e=>{setBookingDate(e.target.value);setBookingTime('')}}/></label>{!needsWhatsappBooking&&<p className="hint">{t('Время обязательно. Свободные интервалы загружаются автоматически.')}</p>}{slotsLoading&&configured&&bookingServices.length>0&&!needsWhatsappBooking&&<p className="hint" role="status">{t('Проверяем свободное время…')}</p>}{!needsWhatsappBooking&&<div className="time-grid">{(bookingServices.length?displayedTimes:[]).map(t=><button key={t} className={bookingTime===t?'selected':''} onClick={()=>setBookingTime(t)}>{t}</button>)}</div>}{!bookingServices.length?<p className="hint">{t("Сначала выберите услугу.")}</p>:needsWhatsappBooking?<p className="hint">{t("Если процедуры занимают более 210 минут, согласуйте запись через WhatsApp.")}</p>:!displayedTimes.length?<div><p className="hint">{t("Для выбранной даты нет доступного времени.")}</p><button type="button" className="text-link" onClick={sendBookingToWhatsapp}>{t("Согласовать через WhatsApp")} <ArrowUpRight size={15}/></button></div>:<p className="hint">{t("Выбранное время подтверждается администратором.")}</p>}</div><div className="booking-step"><h3><span>04</span>  {t("Контактные данные")}</h3><div className="two-fields"><label className="field">{t("Ваше имя")}<input value={customer.name} onChange={e=>setCustomer({...customer,name:e.target.value})} placeholder={t("Как к вам обращаться")}/></label><PhoneField label={t('Телефон')} country={bookingPhoneCountry} onCountryChange={setBookingPhoneCountry} value={customer.phone} onChange={phone=>setCustomer(old=>({...old,phone}))}/></div><label className="field">{t("Комментарий")}<textarea rows={3} value={customer.note} onChange={e=>setCustomer({...customer,note:e.target.value})} placeholder={t("Если есть пожелания")}/></label><label className="consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/>  {t("Согласен(на) на обработку предоставленных контактных данных для записи")}</label>{needsWhatsappBooking&&<p className="hint">{t("Для длительных процедур свяжитесь с салоном. Сообщение нужно отправить в WhatsApp вручную.")}</p>}<button className="btn btn-primary" disabled={bookingBusy||(!needsWhatsappBooking&&(!bookingTime||!displayedTimes.includes(bookingTime)))} onClick={needsWhatsappBooking?sendBookingToWhatsapp:submitBooking}>{bookingBusy?t("Отправляем заявку…"):needsWhatsappBooking?t("Согласовать через WhatsApp"):t("Отправить заявку")} {bookingBusy?<span className="btn-spinner" aria-hidden="true"/>:<ArrowUpRight size={17}/>}</button></div></div><aside className="booking-summary"><div className="eyebrow">{t("ВАША ЗАПИСЬ")}</div><h3>{t("Красота в деталях")}</h3><div>{picked.length?picked.map(s=><div className="summary-row" key={s.id}><span>{itemText(s,'name',s.name)}</span><b>{money(s.price)}</b></div>):<p>{t("Услуги ещё не выбраны")}</p>}</div><div className="summary-row"><span>{t("Длительность")}</span><b>{duration}  {t("мин")}</b></div><div className="summary-row"><span>{t("Дата / время")}</span><b>{bookingDate} {needsWhatsappBooking?t("Время согласовывается"):bookingTime}</b></div><div className="summary-total"><span>{t("Ориентировочно")}</span><strong>{t("от")} {money(total)}</strong></div><small>{t("Стоимость может измениться после консультации.")}</small></aside></div>}</Section>;
 const ShopPage=()=> <Section eyebrow="BEAUTY SHOP" title="Красота в каждом дне">{!content.shopEnabled?<p>{t("Магазин временно недоступен.")}</p>:<><div className="filter-bar"><SearchField value={query} onChange={setQuery} placeholder={t("Поиск товара")}/><div className="chips">{productCategories.map(c=><button className={productCat===c?'selected':''} key={c} onClick={()=>setProductCat(c)}>{c==='Все'?t(c):itemText(state.categories.find(x=>x.name===c),'name',c)}</button>)}</div></div><div className="card-grid">{activeProducts.filter(p=>(productCat==='Все'||p.category===productCat)&&p.name.toLowerCase().includes(query.toLowerCase())).map(p=><article className="service-card" key={p.id}><button type="button" className="card-photo detail-photo-button" onClick={()=>openDetail('product',p.id)} aria-label={`${t('Подробнее о товаре:')} ${itemText(p,'name',p.name)}`}><MediaImage src={p.image} alt={itemText(p,'name',p.name)} loading="lazy"/></button><div className="card-body"><div className="muted small">{itemText(state.categories.find(c=>c.kind==='product'&&c.name===p.category),'name',p.category)}</div><button type="button" className="detail-title" onClick={()=>openDetail('product',p.id)}><h3>{itemText(p,'name',p.name)}</h3></button><div className="card-bottom"><strong>{money(p.price)}</strong><button className={`product-add-btn ${addedProductId===p.id?'is-added':''}`} onClick={()=>addProduct(p)} aria-label={`${t('В корзину:')} ${itemText(p,'name',p.name)}`} aria-live="polite">{addedProductId===p.id?<><Check size={18}/><span>{t('Добавлено')}</span></>:<ShoppingCart size={18}/>}</button></div></div></article>)}</div></>}</Section>;
 const AccountPage=()=> <Section eyebrow="ЛИЧНЫЙ КАБИНЕТ" title="Мой профиль">{!authUser?<div className="account-panel"><Lock size={26}/><p>{t("Доступ к личному кабинету открыт только зарегистрированным клиентам. Создайте аккаунт или войдите, чтобы видеть свои записи и заказы.")}</p><button className="btn btn-primary" onClick={()=>{setAuthMode('login');setAuthOpen(true)}}>{t("Войти в кабинет")}</button><button className="btn btn-outline" onClick={()=>{setAuthMode('signup');setAuthOpen(true)}}>{t("Регистрация")}</button></div>:<div className="account-panel"><p>{t("Вы вошли как")} <strong>{authUser.email}</strong></p><button className="text-link" onClick={()=>auth&&void signOut(auth).then(()=>alert(t("Вы вышли из аккаунта"))).catch(()=>alert(t("Не удалось выйти из аккаунта")))}>{t("Выйти из аккаунта")}</button><h3>{t("Мои записи")}</h3>{myBookings.length?myBookings.map(b=><div className="account-item" key={b.id}><b>{b.date} · {b.time}</b><span>{b.serviceIds.map((id,index)=>b.serviceNames?.[index]||state.services.find(x=>x.id===id)?.name||id).join(', ')}</span><small>{t("Статус:")} {t(b.status)}</small></div>):<p>{t("Пока нет записей в этом аккаунте. Гостевые заявки не привязываются автоматически к профилю.")}</p>}<h3>{t("Мои заказы")}</h3>{myOrders.length?myOrders.map(o=><div className="account-item" key={o.id}><b>{t("Заказ #")}{o.id.slice(0,8)}</b><span>{money(o.total)}</span></div>):<p>{t("Пока нет заказов.")}</p>}</div>}</Section>;
 const DetailsPage=()=>{const item=detail?.type==='service'?state.services.find(s=>s.id===detail.id):detail?.type==='product'?state.products.find(p=>p.id===detail.id):state.masters.find(m=>m.id===detail?.id);if(!detail||!item)return <Section eyebrow="ИНФОРМАЦИЯ" title="Не найдено"><button className="btn btn-outline" onClick={()=>go('Главная')}>{t("На главную")}</button></Section>;const isService=detail.type==='service',isProduct=detail.type==='product',asService=isService?item as Service:null,asProduct=isProduct?item as Product:null,asMaster=detail.type==='master'?item as Master:null;return <Section eyebrow={isService?'ПОДРОБНО ОБ УСЛУГЕ':isProduct?'ПОДРОБНО О ТОВАРЕ':'НАШ МАСТЕР'} title={itemText(item,'name',item.name)}><div className="detail-layout"><div className="detail-visual"><MediaImage src={item.image} alt={itemText(item,'name',item.name)}/></div><div className="detail-info"><div className="eyebrow">{asService?itemText(state.categories.find(c=>c.kind==='service'&&c.name===asService.category),'name',asService.category):asProduct?itemText(state.categories.find(c=>c.kind==='product'&&c.name===asProduct.category),'name',asProduct.category):asMaster?itemText(asMaster,'specialty',asMaster.specialty):''}</div><p className="lead">{asService?itemText(asService,'description',asService.description):asProduct?itemText(asProduct,'description',asProduct.description):asMaster?itemText(asMaster,'specialty',asMaster.specialty):t('Описание обновляется администратором.')}</p>{asService&&<><p><b>{t("Продолжительность:")}</b> {asService.duration}  {t("мин")}</p><h3>{t("Стоимость от")} {money(asService.price)}</h3><p className="hint">{t("Фактическая цена уточняется после консультации.")}</p><button className="btn btn-primary" onClick={()=>{setBookingServices([asService.id]);go('Запись')}}>{t("Записаться на услугу")} <ArrowUpRight size={17}/></button></>}{asProduct&&<><h3>{money(asProduct.price)}</h3><button className={`btn btn-primary ${addedProductId===asProduct.id?'cart-added':''}`} onClick={()=>addProduct(asProduct)}>{addedProductId===asProduct.id?t('Добавлено'):t('В корзину')} {addedProductId===asProduct.id?<Check size={17}/>:<ShoppingCart size={17}/>}</button></>}{asMaster&&<><h3>{t("Услуги мастера")}</h3><div className="detail-services">{state.services.filter(s=>asMaster.serviceIds.includes(s.id)).map(s=><button key={s.id} onClick={()=>openDetail('service',s.id)}>{itemText(s,'name',s.name)} <ArrowUpRight size={15}/></button>)}</div><button className="btn btn-primary" onClick={()=>{setBookingMaster(asMaster.id);go('Запись')}}>{t("Записаться к мастеру")} <ArrowUpRight size={17}/></button></>}<button className="text-link" onClick={()=>go(isService?'Услуги':isProduct?'Магазин':'Мастера')}>{t("← Вернуться к списку")}</button></div></div></Section>};
 const CartPage=()=> <Section eyebrow="ВАШ ВЫБОР" title="Корзина и заказ">{orderSuccess&&<div className="success-box" role="status"><Check size={34}/><h3>{t('Заказ успешно отправлен')}</h3><p>{t('Заказ №')} {orderSuccess.id.slice(0,8)}. {t('Заявка сохранена и доступна администратору.')}</p><button className="btn btn-primary" onClick={()=>go('Кабинет')}>{t('Мои заказы')} <ArrowRight size={16}/></button>{(()=>{const number=(content.whatsapp||import.meta.env.VITE_SALON_WHATSAPP||'').replace(/\D/g,'');return number?<button type="button" className="btn btn-outline" onClick={()=>wa(`Здравствуйте! Заказ EL BEM №${orderSuccess.id.slice(0,8)}. ${orderSuccess.items.map(i=>`${i.name} × ${i.quantity}`).join(', ')}. Итого: ${money(orderSuccess.total)}.`)}>{t('Отправить в WhatsApp')}</button>:null})()}{orderChannel==='telegram'&&telegramOwnerLink()&&<button type="button" className="btn btn-outline" onClick={()=>{const link=telegramOwnerLink();if(link)window.open(link,'_blank','noopener,noreferrer');const message=`EL BEM — заказ №${orderSuccess.id.slice(0,8)}\nКлиент: ${orderSuccess.name}\nТелефон: ${orderSuccess.phone}\nТовары: ${orderSuccess.items.map(i=>`${i.name} × ${i.quantity}`).join(', ')}\nСумма: ${money(orderSuccess.total)}`;void navigator.clipboard?.writeText(message).then(()=>notify(t('Детали заказа скопированы. Вставьте текст в Telegram и отправьте вручную.'),'info')).catch(()=>notify(t('Telegram открыт. Отправьте детали заказа владельцу вручную.'),'info'))}}>{t('Открыть Telegram владельца')}</button>}<button className="btn btn-outline" onClick={()=>{setOrderSuccess(null);go('Магазин')}}>{t('Продолжить покупки')}</button></div>}{!orderSuccess&&<div className="cart-layout"><div>{Object.entries(cart).length?Object.entries(cart).map(([id,qty])=>{const p=state.products.find(x=>x.id===id);if(!p)return null;return <div className="cart-row" key={id}><MediaImage src={p.image} alt={itemText(p,'name',p.name)}/><div><b>{itemText(p,'name',p.name)}</b><p>{money(p.price)}</p></div><div className="qty"><button onClick={()=>setCart(c=>{const next={...c};if(next[id]<=1)delete next[id];else next[id]--;return next})}><Minus size={14}/></button>{qty}<button onClick={()=>setCart(c=>({...c,[id]:Math.min(20,c[id]+1)}))}><Plus size={14}/></button></div><button onClick={()=>setCart(c=>{const n={...c};delete n[id];return n})}><Trash2 size={17}/></button></div>}):<p className="lead">{t("Пока пусто. Выберите товары в магазине.")}</p>}</div><div className="checkout"><div className="eyebrow">{t("ОФОРМЛЕНИЕ")}</div><h3>{t("Итого:")} {money(cartTotal)}</h3><label className="field">{t("Имя")}<input value={orderName} onChange={e=>setOrderName(e.target.value)} placeholder={t("Ваше имя")}/></label><PhoneField label={t('Телефон')} country={orderPhoneCountry} onCountryChange={setOrderPhoneCountry} value={orderPhone} onChange={setOrderPhone}/><button className="btn btn-primary" disabled={orderBusy} onClick={()=>void submitOrder()}>{orderBusy?t('Отправляем заказ…'):t('Оформить заказ')} {orderBusy?<span className="btn-spinner" aria-hidden="true"/>:<ArrowRight size={16}/>}</button>{telegramOwnerLink()&&<button className="btn btn-outline checkout-telegram" disabled={orderBusy} onClick={()=>void submitOrder('telegram')}>{orderBusy?t('Отправляем заказ…'):t('Заказать через Telegram')} {orderBusy?<span className="btn-spinner" aria-hidden="true"/>:<MessageCircle size={16}/>}</button>}{telegramOwnerLink()&&<p className="checkout-contact-note">{t("Telegram открывает чат владельца. Сообщение необходимо отправить вручную.")}</p>}</div></div>}</Section>;
 const GalleryPage=()=> <Section eyebrow="ПОРТФОЛИО" title="Вдохновение в деталях"><div className="gallery-full">{mediaGallery.map((img,i)=><MediaImage src={img} key={img} alt={`Работа ${i+1}`} loading="lazy"/>)}</div></Section>;
 const AcademyPage=()=> <Section eyebrow="EL BEM ACADEMY" title={siteText('academyTitle')}><div className="academy-highlight"><MediaImage src={content.academyImage} alt={t("Обучение")}/><div><p>{siteText('academyText')}</p><div className="chips"><span className="chip-static">{t("Практика")}</span><span className="chip-static">{t("Консультация")}</span><span className="chip-static">{t("Индивидуальный подход")}</span></div><button className="btn btn-primary" onClick={()=>wa('Здравствуйте! Хочу узнать об обучении в EL BEM.')}>{t("Узнать об обучении в WhatsApp")} <ArrowUpRight size={16}/></button></div></div></Section>;
 const AboutPage=()=> <Section eyebrow="О НАС" title={siteText('aboutTitle')}><div className="feature-grid about-page"><div><p className="lead">{siteText('aboutText')}</p><p>{siteText('address')||t('Узген, Кыргызстан')}</p><button className="btn btn-primary" onClick={()=>go('Запись')}>{t("Записаться")} <ArrowRight size={16}/></button></div><MediaImage src={mediaGallery[0]} alt="EL BEM"/></div></Section>;
 const [reviewName,setReviewName]=useState('');const [reviewText,setReviewText]=useState('');const [reviewRating,setReviewRating]=useState(5);
 const sendReview=async()=>{try{if(!configured){alert(t('Для публикации отзыва необходимо войти в личный кабинет'));return}await submitReview(reviewName,reviewText,reviewRating);setReviewText('');alert(t('Отзыв отправлен на модерацию'))}catch(e){alert(String(e))}};
 const ReviewsPage=()=> <Section eyebrow="ОТЗЫВЫ" title="Ваши слова важны"><div className="review-grid">{state.reviews.filter(r=>r.approved!==false).map(r=><div className="review-card" key={r.id}><RatingStars rating={r.rating}/><p>“{r.text}”</p><b>{r.name}</b>{r.image?<MediaImage src={r.image} alt={t("Прикреплённый отзыв")}/>:null}</div>)}</div><div className="review-submission"><h3>{t("Оставить отзыв")}</h3>{!authUser?<p className="hint">{t("Для отзыва войдите в личный кабинет.")}</p>:<div className="form-grid"><label className="field">{t("Ваше имя")}<input value={reviewName} onChange={e=>setReviewName(e.target.value)}/></label><label className="field">{t("Оценка")}<select value={reviewRating} onChange={e=>setReviewRating(Number(e.target.value))}>{[5,4,3,2,1].map(n=><option key={n} value={n}>{n} ★</option>)}</select></label><label className="field">{t("Ваш отзыв")}<textarea value={reviewText} onChange={e=>setReviewText(e.target.value)} /></label><button className="btn btn-primary" onClick={sendReview}>{t("Отправить на модерацию")}</button></div>}</div></Section>;
 const ContactPage=()=> <Section eyebrow="КОНТАКТЫ" title="Будем рады вам"><div className="contact-cards"><div><MapPin/><h3>{siteText('address')||t('Узген · Кыргызстан')}</h3><p>{siteText('openingHours')||t('Часы работы уточняются')}</p>{salonMapLink()&&<a className="text-link address-link" href={salonMapLink()!} target="_blank" rel="noopener noreferrer">{t("Открыть на карте")} <ArrowUpRight size={16}/></a>}</div><div><Instagram/><h3>Instagram</h3><a href="https://www.instagram.com/ozgon.salon.el_bem/" target="_blank" rel="noreferrer">@ozgon.salon.el_bem <ArrowUpRight size={15}/></a><p>{t("Свяжитесь с нами для записи и консультации.")}</p><button className="btn btn-primary" onClick={()=>wa('Здравствуйте! У меня вопрос о салоне.')}>WhatsApp <ArrowRight size={15}/></button></div></div></Section>;
 const [edit,setEdit]=useState<Record<string,any>|null>(null);const [editTable,setEditTable]=useState<'services'|'masters'|'products'|'reviews'|null>(null);const [saving,setSaving]=useState(false);const [scheduleMaster,setScheduleMaster]=useState('');const [scheduleDate,setScheduleDate]=useState(today());const [scheduleTime,setScheduleTime]=useState('09:00');
 const openEdit=(table:'services'|'masters'|'products'|'reviews',v?:any)=>{setEditTable(table);setEdit(v||({id:uid(),name:'',image:'',category:'',price:0,duration:60,description:'',serviceIds:[],active:true,text:'',rating:5,approved:true}))};
 const [categoryEdit,setCategoryEdit]=useState<CatalogCategory|null>(null);
 const categorySave=async()=>{if(!categoryEdit)return;notify(t('Сохраняем категорию…'),'pending');const value={...categoryEdit,name:categoryEdit.name.trim()};if(!value.name){alert(t('Укажите название категории'));return}if(state.categories.some(c=>c.id!==value.id&&c.kind===value.kind&&c.name.toLowerCase()===value.name.toLowerCase())){alert(t('Такая категория уже существует'));return}
 const old=state.categories.find(c=>c.id===value.id);const table=value.kind==='service'?'services':'products';const renamed=old&&old.name!==value.name?(state[table] as (Service|Product)[]).filter(item=>item.category===old.name):[];
 try{if(!configured)throw Error(t('Firebase не подключён. Проверьте .env.local и переменные Vercel.'));await saveCategory(value);if(old&&old.name!==value.name)await renameCatalogCategory(value.kind,old.name,value.name,renamed);
 setState(prev=>({...prev,categories:[...prev.categories.filter(c=>c.id!==value.id),value],services:value.kind==='service'?prev.services.map(x=>x.category===old?.name?{...x,category:value.name}:x):prev.services,products:value.kind==='product'?prev.products.map(x=>x.category===old?.name?{...x,category:value.name}:x):prev.products}));setCategoryEdit(null);notify(t('Категория сохранена'),'success')}catch(e){console.error('Category save failed',e);notify(saveErrorText(e),'error')}};
 const categoryDelete=async(c:CatalogCategory)=>{if([...state.services,...state.products].some(x=>x.category===c.name)){alert(t('Категория используется. Сначала перенесите связанные товары или услуги.'));return}if(!confirm(t('Удалить категорию?')))return;try{if(!configured)throw Error(t('Firebase не подключён.'));await deleteEntity('categories',c.id);setState(prev=>({...prev,categories:prev.categories.filter(x=>x.id!==c.id)}));alert(t('Категория удалена'))}catch(e){alert(String(e))}};
 const [uploading,setUploading]=useState(false);
 const [weekday,setWeekday]=useState(1);const [opening,setOpening]=useState('09:00');const [closing,setClosing]=useState('19:00');const [working,setWorking]=useState(true);
 const [weeklyHours,setWeeklyHours]=useState<{master_id:string;weekday:number;open_at:string;close_at:string;is_open:boolean}[]>([]);
 const [passwordBusy,setPasswordBusy]=useState(false);const [currentAdminPassword,setCurrentAdminPassword]=useState('');const [newAdminPassword,setNewAdminPassword]=useState('');
 useEffect(()=>{if(!configured||!adminAuth)return;void getMasterHours().then(setWeeklyHours).catch(e=>{console.error('Data connection error',e);setConnectedError(String(e))})},[adminAuth]);
 useEffect(()=>{const row=weeklyHours.find(x=>x.master_id===scheduleMaster&&x.weekday===weekday);setOpening((row?.open_at||'09:00').slice(0,5));setClosing((row?.close_at||'19:00').slice(0,5));setWorking(row?.is_open??true)},[scheduleMaster,weekday,weeklyHours]);
 const saveWeekly=async()=>{if(!scheduleMaster){alert(t('Сначала выберите мастера'));return}if(closing<=opening){alert(t('Конец смены должен быть позже начала'));return}const row={master_id:scheduleMaster,weekday,open_at:opening,close_at:closing,is_open:working};notify(t('Сохраняем график…'),'pending');try{if(!configured)throw Error(t('Firebase не подключён. Проверьте .env.local и переменные Vercel.'));await saveMasterHour(row);setWeeklyHours(old=>[...old.filter(x=>!(x.master_id===scheduleMaster&&x.weekday===weekday)),row]);notify(t('График сохранён'),'success')}catch(e){console.error('Schedule save failed',e);notify(saveErrorText(e),'error')}};
 const changeAdminPassword=async()=>{
  if(passwordBusy)return;
  if(!configured||!ownerFirebaseAuth?.currentUser?.email||!adminAuth){notify(t('Войдите в административный аккаунт.'),'error');return}
  if(!currentAdminPassword||newAdminPassword.length<12){notify(t('Введите текущий пароль и новый пароль от 12 символов'),'error');return}
  setPasswordBusy(true);notify(t('Проверяем пароль и сохраняем…'),'pending');
  try{
    if(!await checkAdmin())throw Error(t('У аккаунта нет роли администратора admin:true.'));
    const user=ownerFirebaseAuth.currentUser;
    const credential=EmailAuthProvider.credential(user.email!,currentAdminPassword);
    await reauthenticateWithCredential(user,credential);
    await updatePassword(user,newAdminPassword);
    setCurrentAdminPassword('');setNewAdminPassword('');
    notify(t('Пароль администратора успешно изменён'),'success');
  }catch(error){console.error('Admin password change failed',error);notify(formatAuthError(error,t),'error')}
  finally{setPasswordBusy(false)}
 };
 const uploadImage=async(file:File,onSaved:(url:string)=>void)=>{
  if(!/^image\/(jpeg|png|webp|gif|avif)$/.test(file.type)){notify(t('Выберите JPEG, PNG, WebP, GIF или AVIF. HEIC сначала переведите в JPEG.'),'error');return}
  if(file.size>10*1024*1024){notify(t('Размер изображения не должен превышать 10 МБ'),'error');return}
  setUploading(true);
  notify(t('Обрабатываем фотографию…'),'pending');
  try{
    if(import.meta.env.VITE_CLOUDINARY_CLOUD_NAME&&import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET){
      if(!adminAuth)throw Error(t('Войдите в административный аккаунт.'));
      const url=await uploadCloudinaryImage(file);
      onSaved(url);
      notify(t('Фото загружено. Нажмите «Сохранить», чтобы опубликовать изменение.'),'success');
    }else{
      const localUrl=await saveLocalImage(file);
      onSaved(localUrl);
      notify(t('Локальный предпросмотр готов. Для публикации на других устройствах добавьте HTTPS-ссылку или настройте Cloudinary.'),'info');
    }
  }catch(error){notify(t('Не удалось загрузить изображение:')+' '+String(error),'error')}
  finally{setUploading(false)}
 };

 const uploadAudio=async(file:File,onSaved:(url:string)=>void)=>{const types=['audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/ogg','audio/mp4','audio/x-m4a'];if(!types.includes(file.type)&&!/\.(mp3|wav|ogg|m4a)$/i.test(file.name)){alert(t('Допустимые форматы: MP3, WAV, OGG, M4A'));return}if(file.size>20*1024*1024){alert(t('Для музыки установлен лимит 20 МБ'));return}setUploading(true);try{if(configured){alert(t('Добавьте публичную ссылку на аудиофайл и сохраните настройки.'));return;}else{onSaved(URL.createObjectURL(file));alert(t('Музыка загружена. Настройки начнут действовать после сохранения.'))}}catch(e){alert('Не удалось загрузить аудио: '+String(e))}finally{setUploading(false)}};
 const saveEdit=async()=>{if(!edit||!editTable||saving)return;setSaving(true);notify(t('Сохраняем изменения…'),'pending');try{if(!configured)throw Error(t('Firebase не подключён. Проверьте .env.local и переменные Vercel.'));{if(typeof edit.image==='string'&&/^(blob:|data:)/i.test(edit.image))throw Error('Фото с устройства нельзя сохранять как ссылку. Используйте HTTPS или /images/имя.jpg.');const payload={...edit};if(editTable==='reviews'){delete payload.active;payload.rating=Math.max(1,Math.min(5,Number(payload.rating)||5));}await saveEntity(editTable,payload)}change(editTable,[...(state[editTable] as any[]).filter(x=>x.id!==edit.id),edit] as any);setEdit(null);notify(t('Сохранено'),'success')}catch(e){notify(saveErrorText(e),'error')}finally{setSaving(false)}};
 const remove=async(table:'services'|'masters'|'products'|'reviews',id:string)=>{if(!confirm(t('Удалить запись? Для коммерческой базы важна история связанных заказов.')))return;try{if(!configured)throw Error(t('Firebase не подключён.'));await deleteEntity(table,id);change(table,(state[table] as any[]).filter(x=>x.id!==id) as any);alert(t('Удалено'))}catch(e){alert(String(e))}};
 const updateBooking=async(b:Booking,status:Booking['status'])=>{
  notify(t('Сохраняем изменения…'),'pending');
  try{if(!configured)throw Error(t('Firebase не подключён.'));await updateBookingStatus(b.id,status);
    change('bookings',state.bookings.map(x=>x.id===b.id?{...x,status}:x));notify(t('Статус обновлён'),'success')
  }catch(e){notify(saveErrorText(e),'error')}
 };
 const salonMapLink=()=>{try{const raw=(content.addressMapUrl||'').trim();if(!raw)return null;const url=new URL(raw);return ['https:','http:'].includes(url.protocol)?url.href:null}catch{return null}};
 const telegramOwnerLink=()=>{const raw=(content.telegramOwner||'').trim();const match=raw.match(/^(?:@|https?:\/\/(?:www\.)?t\.me\/)?([A-Za-z][A-Za-z0-9_]{4,31})\/?$/i);return match?`https://t.me/${match[1]}`:null};
 const bookingTelegramText=(b:Booking)=>`EL BEM — заявка #${b.id.slice(0,8)}\nКлиент: ${b.name}\nТелефон: ${b.phone}\nУслуги: ${b.serviceIds.map((id,index)=>b.serviceNames?.[index]||state.services.find(s=>s.id===id)?.name||id).join(', ')}\nМастер: ${b.masterName||state.masters.find(m=>m.id===b.masterId)?.name||'Любой свободный'}\nДата: ${b.date} ${b.time}\nСтатус: ${b.status}\nКомментарий: ${b.note||'—'}`;
 const sendTelegramManually=async(b:Booking)=>{const link=telegramOwnerLink();if(!link){alert(t('Сначала укажите @username владельца Telegram в Настройках и сохраните. Номер телефона не подходит.'));setAdminPage('Настройки');return}try{await navigator.clipboard.writeText(bookingTelegramText(b));window.open(link,'_blank','noopener,noreferrer');alert(t('Заявка скопирована. В открывшемся Telegram вставьте текст и нажмите «Отправить». Автоматической отправки нет.'))}catch{window.open(link,'_blank','noopener,noreferrer');alert(t('Telegram открыт. Скопируйте данные заявки вручную: браузер запретил доступ к буферу обмена.'))}};
 const persistPromotions=async(updated:Promotion[])=>{
  if(promotionBusy)return false;
  if(!configured){alert(t('Сервис временно недоступен. Попробуйте позже.'));return false;}
  setPromotionBusy(true);notify(t('Сохраняем акцию…'),'pending');
  try{
    await saveEntity('site_content',{id:'main',data:{promotions:updated}});
    setState(old=>({...old,content:{...old.content,promotions:updated}}));
    setDismissedPromotion(null);
    notify(t('Акция сохранена и опубликована на сайте'),'success');
    return true;
  }catch(error){console.error('Promotion save failed',error);notify(t('Не удалось сохранить акцию. Проверьте доступ и повторите.')+' '+saveErrorText(error),'error');return false;}
  finally{setPromotionBusy(false)};
};
 const saveErrorText=(error:unknown)=>{
  const code=typeof error==='object'&&error!==null&&'code' in error?String(error.code):'';
  if(code==='permission-denied')return t('Firebase запретил сохранение: проверьте роль администратора и Firestore Rules.');
  if(code==='unauthenticated')return t('Сеанс администратора завершился. Войдите заново.');
  if(code==='unavailable'||code==='deadline-exceeded')return t('Нет связи с Firebase. Проверьте интернет и повторите сохранение.');
  if(code==='resource-exhausted')return t('Лимит Firebase исчерпан. Проверьте использование Firestore.');
  if(code==='failed-precondition')return t('Firestore отклонил операцию. Проверьте настройки базы и правила доступа.');
  return (error instanceof Error?error.message:String(error))||t('Не удалось сохранить изменения.');
 };
 const saveContent=async()=>{
  if(contentSaveBusy)return;
  setContentSaveBusy(true);setContentSaveFeedback(null);notify(t('Сохраняем изменения…'),'pending');
  const versionAtSave=contentEditVersion.current;
  try{
   if(!configured)throw Error(t('Firebase не подключён. Проверьте .env.local и переменные Vercel.'));
   if(!ownerFirebaseAuth?.currentUser||!adminAuth)throw Error(t('Войдите в административный аккаунт перед сохранением.'));
   if(!await checkAdmin())throw Error(t('У аккаунта нет роли администратора admin:true.'));
   if([content.heroImage,content.academyImage,content.musicUrl,...(content.galleryImages||[])].some(x=>typeof x==='string'&&/^(blob:|data:)/i.test(x)))throw Error(t('Локальный файл недоступен другим устройствам. Используйте HTTPS-ссылку или файл из public.'));
   setVolumeDirty(false);await volumeWriteQueue.current.catch(()=>undefined);await saveEntity('site_content',{id:'main',data:content});
   if(contentEditVersion.current===versionAtSave){contentDraftDirty.current=false;volumeEditInProgress.current=false;setVolumeState('saved');}
   const message=contentEditVersion.current===versionAtSave?t('Изменения сохранены в Firebase.'):t('Часть изменений сохранена. Есть новые несохранённые правки.');
   setContentSaveFeedback({error:false,message});notify(message,'success');
  }catch(error){console.error('Site content save failed',error);const message=saveErrorText(error);setContentSaveFeedback({error:true,message});notify(message,'error')}
  finally{setContentSaveBusy(false)}
 };
 const addBlock=async()=>{const slot=scheduleMaster?`${scheduleMaster}|${scheduleDate}|${scheduleTime}`:`${scheduleDate}|${scheduleTime}`;if(state.blocked.includes(slot))return;try{if(!configured)throw Error(t('Firebase не подключён.'));await saveEntity('blocked_slots',{slot});change('blocked',[...state.blocked,slot]);alert(t('Интервал закрыт'))}catch(e){alert(String(e))}};
